import sys

def mobius(n):
    if n == 1:
        return 1
    mu = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            count = 0
            while n % i == 0:
                n = n // i
                count += 1
            if count >= 2:
                return 0
            mu *= -1
        i += 1
    if n > 1:
        mu *= -1
    return mu

def main():
    K = int(sys.stdin.readline())
    # Precompute Mobius function for numbers 1 to 200
    mobius_list = [0] * (201)  # index 0 unused
    for n in range(1, 201):
        mobius_list[n] = mobius(n)

    total = 0
    for d in range(1, K + 1):
        m = K // d
        inner_sum = 0
        for g in range(1, m + 1):
            mu_g = mobius_list[g]
            term = mu_g * ((m // g) ** 3)
            inner_sum += term
        total += d * inner_sum
    print(total)

